import{_ as l,o as i,c as e,am as o}from"./chunks/framework._FJXuPhs.js";const u=JSON.parse('{"title":"简历 脱敏版本","description":"","frontmatter":{"title":"简历 脱敏版本","excerpt":"摘要","date":"2026-11-04 22:18:58","updated":"2026-11-04 22:18:58"},"headers":[],"relativePath":"面试准备/2026版本/简历 脱敏版本.md","filePath":"面试准备/2026版本/简历 脱敏版本.md","lastUpdated":null}'),t={name:"面试准备/2026版本/简历 脱敏版本.md"};function r(n,a,h,d,s,p){return i(),e("div",null,[...a[0]||(a[0]=[o('<h1 id="java开发工程师-脱敏简历" tabindex="-1">Java开发工程师（脱敏简历） <a class="header-anchor" href="#java开发工程师-脱敏简历" aria-label="Permalink to &quot;Java开发工程师（脱敏简历）&quot;">​</a></h1><p>联系方式：1XX****XXXX | <em><strong>@</strong></em>.com<br> 求职意向：Java | 期望薪资：15-20K | 期望城市：广州</p><h2 id="个人优势" tabindex="-1">个人优势 <a class="header-anchor" href="#个人优势" aria-label="Permalink to &quot;个人优势&quot;">​</a></h2><ol><li>本科毕业，学信网可查；</li><li>六年 Java 开发经验，拥有微服务架构经验；</li><li>熟悉 Spring、SpringMVC、SpringBoot、SpringCloud、MyBatis 等开源框架；</li><li>熟练掌握 MySQL、Redis、Oracle 等数据库，熟练使用 Java 常见组件；</li><li>能够和不同的人合作，具备良好的团队协作精神。</li></ol><h2 id="专业技能" tabindex="-1">专业技能 <a class="header-anchor" href="#专业技能" aria-label="Permalink to &quot;专业技能&quot;">​</a></h2><ul><li>熟悉 volatile、synchronized、Lock、ConcurrentHashMap、线程池等并发编程技术；熟悉 JVM、JMM，熟悉内存模型、类加载、垃圾收集器、GC 算法等，具有生产 JVM 调优经验。</li><li>熟练使用 Redis，熟悉其数据类型、持久化、缓存一致性等，对分布式锁实现有一定的理解。</li><li>熟练使用 MySQL，熟悉底层数据结构、索引、事务、日志等，具有生产慢 SQL 调优经验。</li><li>熟悉 RabbitMQ、RocketMQ，熟悉基础架构、持久化机制、零拷贝以及常见问题解决方案。</li><li>熟悉 Spring，对 IOC、AOP、Bean 生命周期、循环依赖等有一定的理解。</li><li>熟悉 SpringBoot，对常用注解、自动装配原理、Jar 启动流程、自定义 Starter 有一定的理解。</li><li>熟悉 SpringCloud，对常用组件、分布式事务具有一定的理解。</li></ul><h2 id="工作经历" tabindex="-1">工作经历 <a class="header-anchor" href="#工作经历" aria-label="Permalink to &quot;工作经历&quot;">​</a></h2><h3 id="某科技服务公司-java-2024-05-2026-10" tabindex="-1">某科技服务公司 | Java | 2024.05-2026.10 <a class="header-anchor" href="#某科技服务公司-java-2024-05-2026-10" aria-label="Permalink to &quot;某科技服务公司 | Java | 2024.05-2026.10&quot;">​</a></h3><p>驻场项目：某跨境电商平台 - 电商营销中台</p><ol><li>负责营销模块活动下发的流程优化与开发，支撑自营与供应商的线上商品报名全链路闭环及敏捷迭代。</li><li>主导活动体系重构与 SKC 商品属性抽离，运用设计模式（策略/模板）提升代码复用率；基于 ES 嵌套文档实现精准查询与字段级增量更新，大幅提升检索性能。</li><li>开发营销工作台，实现活动流程可视化。</li></ol><h3 id="某物流科技公司-java-2022-11-2024-04" tabindex="-1">某物流科技公司 | Java | 2022.11-2024.04 <a class="header-anchor" href="#某物流科技公司-java-2022-11-2024-04" aria-label="Permalink to &quot;某物流科技公司 | Java | 2022.11-2024.04&quot;">​</a></h3><ol><li>承担部分功能模块的开发，参与相关技术文档的编写。</li><li>参与历史遗留问题的定位与优化。</li><li>参与微服务拆分以及接口重构。</li></ol><h3 id="某信息技术公司-java-2020-07-2022-10" tabindex="-1">某信息技术公司 | Java | 2020.07-2022.10 <a class="header-anchor" href="#某信息技术公司-java-2020-07-2022-10" aria-label="Permalink to &quot;某信息技术公司 | Java | 2020.07-2022.10&quot;">​</a></h3><ol><li>根据需求文档，进行功能模块的设计与开发。</li><li>按照公司技术文档规范编写相关的技术文档。</li><li>负责根据客户需求对产品进行二次开发和持续迭代。</li></ol><h2 id="项目经历" tabindex="-1">项目经历 <a class="header-anchor" href="#项目经历" aria-label="Permalink to &quot;项目经历&quot;">​</a></h2><h3 id="某跨境电商平台-电商营销中台" tabindex="-1">某跨境电商平台 - 电商营销中台 <a class="header-anchor" href="#某跨境电商平台-电商营销中台" aria-label="Permalink to &quot;某跨境电商平台 - 电商营销中台&quot;">​</a></h3><p>项目概述：本平台面向公司内部业务人员及外部供应商，致力于将线下营销活动流程全面线上化。核心涵盖活动管理（AOC 活动、MRS 店铺活动、趋势跟卖活动等）、规则维护、价格体系、供应商报名及店铺运营等模块。实现从商品中台下发的商品拆分、活动下发、自营/供应商报名到预算分配的全链路闭环，大幅降低人工干预与运营成本。</p><p>技术栈：Spring Boot + MySQL + Redis + Elasticsearch + Kafka + XXL-Job + SpringEvent 等。</p><p>职责：</p><ol><li>活动异动流程优化：针对高频活动异动场景，重构处理流程，采用分批消费、小步快跑的异步控制策略，有效平抑系统流量峰值，提升系统吞吐量与稳定性。</li><li>活动体系架构重构：主导 25 年活动体系改造，运用策略模式、模板方法模式对活动核心链路进行抽象。沉淀统一标准模板以支撑 AOC 活动、MRS 店铺活动及趋势跟卖等不同策略的实现，极大提升了代码复用性与后续迭代效率。</li><li>SKC 商品公共属性抽离与 ES 查询优化：主导抽离商品 SKC 公共属性（店铺 ID、商品层次、标签等），构建独立 SKC 表。将公共属性及变更监听统一汇入 ES 大索引集合，针对不同活动 ID 和类型，采用 ES 子集合字段（嵌套文档）精准控制查询范围。同时，实现同一套监听机制下的精准字段级增量更新，大幅降低 ES 写入压力并提升查询性能。</li><li>复杂业务攻坚（扣款与价格体系）：深度参与核心难点开发，针对扣款流程保障资金流转的幂等性与分布式事务一致性；针对价格体系监听变更，基于 MQ 实现事件驱动，保障缓存与底层数据的实时同步与准确性。</li><li>营销工作台建设：负责新增营销工作台模块开发，实现活动全流程可视化与自动化监控，新增预算金额分配及全品策略维护方案，进一步减少业务人员的人工干预。</li><li>大商品列表性能优化：针对大体量商品列表查询场景，引入线程池 + CompletableFuture 进行并发查询与数据聚合，显著缩短接口响应时间（RT）。</li></ol><h3 id="某物流咨询中台-java-开发-2023-02-2024-04" tabindex="-1">某物流咨询中台 | Java 开发 | 2023.02-2024.04 <a class="header-anchor" href="#某物流咨询中台-java-开发-2023-02-2024-04" aria-label="Permalink to &quot;某物流咨询中台 | Java 开发 | 2023.02-2024.04&quot;">​</a></h3><p>项目概述：本平台专门设计用于集中处理司机与货主间的交易纠纷。它通过创建客诉单，实现从纠纷发生到解决的全流程管理。客诉单由客服部门审核，严重问题需领导复审。该平台采用消息队列和同步接口调用，确保与其他部门的高效交互。在财务方面，涉及垫付时会产生催收和申诉单。我们部门专注于平台的持续迭代，以提高客服处理效率和整体服务质量。</p><p>技术栈：SpringBoot + MyBatis + SpringCloud + ES + RocketMQ + Redis + MySQL</p><p>职责：</p><ol><li>负责需求分析与开发，包括客诉单的创建与重开、催收单和申请单等关键功能。</li><li>参与客诉平台服务拆分，拆分成客诉平台、催收平台、申请单平台三个独立的微服务，方便职责划分和后期迭代。</li><li>负责客诉监控平台日常检测慢 SQL 的调优以及针对个别大表制定拆解方案。</li><li>针对服务调用处理耗时过大的问题，采用并行处理服务调用，调用从 10s 压缩到 2s，考虑到 IO 爆炸的问题，部分接口进行缓存、异步处理。</li><li>针对客诉核心创单接口涉及分布式事务问题，采用 RocketMQ 半事务消息编写回滚逻辑。</li><li>针对线上 Redis 内存溢出问题，排查并优化内存使用策略。</li><li>针对创单接口高峰期频繁出现 TP99 耗时变高，分析定位并解决创单接口在高峰期的频繁 FullGC 问题，提升系统稳定性和性能。</li></ol><h3 id="某物流消息中台-java-开发-2022-11-2023-01" tabindex="-1">某物流消息中台 | Java 开发 | 2022.11-2023.01 <a class="header-anchor" href="#某物流消息中台-java-开发-2022-11-2023-01" aria-label="Permalink to &quot;某物流消息中台 | Java 开发 | 2022.11-2023.01&quot;">​</a></h3><p>项目概述：统一整合物流平台的邮件、短信、移动端消息发送功能，独立搭建一套消息发送系统，来接收、发送、重试消息，保障消息的送达率。</p><p>技术栈：SpringBoot、Redis、RocketMQ、MySQL、MyBatis、SpringCloud</p><p>职责：</p><ol><li>阅读接口文档实现短信、邮件接入。</li><li>使用 RocketMQ 来对接其他模块的移动端推送等高频消息发送。</li><li>采用定时任务对不同平台的异常消息进行重试操作。</li><li>使用自定义线程池来对消息进行处理，保证消息中台系统的正常运行。</li></ol><h3 id="某汽车工厂-mes-系统-java-开发-2021-11-2022-10" tabindex="-1">某汽车工厂 MES 系统 | Java 开发 | 2021.11-2022.10 <a class="header-anchor" href="#某汽车工厂-mes-系统-java-开发-2021-11-2022-10" aria-label="Permalink to &quot;某汽车工厂 MES 系统 | Java 开发 | 2021.11-2022.10&quot;">​</a></h3><p>项目概述：为了实现集团化汽车工厂管理，提出了多工厂 MES 管理系统，实现数据互通，提高企业生产和管理效率，也能让管理层能够实时监控设备的生产状态，来调整生产业务线、保证管理有序、产品质量、数据可视化。主要覆盖了汽车制造工艺中的计划、生产、打印、法规模块。</p><p>技术栈：Spring、SpringCloud、MySQL、Redis、MyBatis、Vue</p><p>职责：</p><ol><li>构建邮件发送模块和企微消息发送模块，解耦消息发送流程。</li><li>针对复杂维度业务，采用设计模式处理复杂业务场景，如模板模式规范了 WebService 接口对接流程。</li><li>针对打印模块业务，采用模板、策略、工厂设计模式，定义装车单打印过程标准和实现对对应的多类型打印，使用了 Redis 进行缓存维护数据操作，使用异步 @Async 处理分线打印操作，使用线程池异步记录日志操作。</li><li>优化了计划排产模块的计划导入操作和过点导出操作。</li><li>负责车间报表数据后端获取逻辑的编写。</li></ol><h3 id="某工厂无纸化系统-java-开发-2021-03-2021-10" tabindex="-1">某工厂无纸化系统 | Java 开发 | 2021.03-2021.10 <a class="header-anchor" href="#某工厂无纸化系统-java-开发-2021-03-2021-10" aria-label="Permalink to &quot;某工厂无纸化系统 | Java 开发 | 2021.03-2021.10&quot;">​</a></h3><p>项目概述：实现线体车体装配、关键件绑定等业务的线上化、数字化，提高工厂总装的生产制造效率，开发并投入使用了总装无纸化系统。</p><p>技术栈：SpringBoot、MySQL、Redis、RocketMQ、MyBatis-Plus、FastDFS</p><p>职责：</p><ol><li>参与系统的全周期开发、测试和优化，提升了生产效率和操作便捷性。</li><li>需求调研和部分后端接口开发，开发了车间的装配关键件绑定、车辆指示、不良录入等功能。</li><li>负责质量关键件绑定模块，实现了表单重复提交校验、关键件绑定、重绑定、解绑等功能。</li></ol><h3 id="某汽车制造-mes-系统-java-开发-2020-07-2021-02" tabindex="-1">某汽车制造 MES 系统 | Java 开发 | 2020.07-2021.02 <a class="header-anchor" href="#某汽车制造-mes-系统-java-开发-2020-07-2021-02" aria-label="Permalink to &quot;某汽车制造 MES 系统 | Java 开发 | 2020.07-2021.02&quot;">​</a></h3><p>项目概述：该系统是汽车制造生产执行系统，涵盖焊装、涂装、总装、VQ、法规和电池车间等多个车间，涉及到计划、生产、质量管控、打印、法规、接口等多个模块。</p><p>技术栈：SpringBoot、MySQL、Redis、RocketMQ</p><p>职责：</p><ol><li>参与日常慢 SQL、接口性能调优。</li><li>负责后端项目搭建，参与系统的全周期开发、测试和优化。</li><li>通过 Socket 通讯实现质量车间的线体车辆实时推送。</li><li>实现表单重复校验，避免后端业务无效执行操作。</li></ol><h2 id="教育经历" tabindex="-1">教育经历 <a class="header-anchor" href="#教育经历" aria-label="Permalink to &quot;教育经历&quot;">​</a></h2><p>某本科院校 | 本科 | 软件工程 | 2016-2020</p><h2 id="资格证书" tabindex="-1">资格证书 <a class="header-anchor" href="#资格证书" aria-label="Permalink to &quot;资格证书&quot;">​</a></h2><ul><li>大学英语四级</li><li>软件设计师</li></ul>',49)])])}const S=l(t,[["render",r]]);export{u as __pageData,S as default};
